import {makePlan,normalize,searchCatalog,recognitionStatus,validateReferenceCatalog} from './lesson-engine.js';
import {ALPHABET,ALPHABET_ENTRIES} from './alphabet.js';
import {loadReferences,saveReferences} from './storage.js';
const $=id=>document.getElementById(id);
const ILY={id:'asl-ily-starter',language:'ASL',label:'I love you',aliases:['ILY','ILoveYou'],source:'MediaPipe ASL starter',referenceUrl:'https://ai.google.dev/edge/mediapipe/solutions/vision/gesture_recognizer',kind:'reference',category:'Starter',media:null,instruction:'Extend your thumb, index and little finger. Fold your middle and ring fingers. Hold briefly with your hand clearly visible.'};
export function createLearningUI(api){
  let catalog=[],imported=[],meta=null,plan=null,current=0,page=0,letter='',loadError=false,searchTimer=null,advanceTimer=null;
  const preview=$('practice-preview'),previewCtx=preview.getContext('2d');
  function entries(){return [ILY,...api.getEntries().filter(e=>e.kind!=='neutral').map(e=>({...e,id:'personal-ref-'+e.id,personalId:e.id,kind:'personal',category:'Your recordings',aliases:[],referenceUrl:e.language==='ISL'?'https://islrtc.nic.in/':'https://www.lifeprint.com/dictionary.htm',source:'Your recorded vocabulary',media:null})),...imported,...catalog,...ALPHABET_ENTRIES];}
  function categories(){const lang=$('catalog-language').value,previous=$('catalog-category').value;$('catalog-category').replaceChildren();const all=document.createElement('option');all.value='';all.textContent='All categories';$('catalog-category').append(all);for(const c of [...new Set(entries().filter(e=>e.language===lang).map(e=>e.category||'Dictionary'))].sort()){const o=document.createElement('option');o.value=c;o.textContent=c;$('catalog-category').append(o);}if([...$('catalog-category').options].some(o=>o.value===previous))$('catalog-category').value=previous;}
  function renderCatalog(){
    const lang=$('catalog-language').value,result=searchCatalog(entries(),{language:lang,query:$('catalog-search').value,letter,category:$('catalog-category').value,page});page=result.page;$('catalog-results').replaceChildren();
    for(const entry of result.entries){const card=document.createElement('article');card.className='sign-card reference-card';const status=recognitionStatus(entry,api.getEntries(),api.getModels());const badge=document.createElement('span');badge.className='badge';badge.textContent=entry.media?'SOURCE VIDEO':entry.kind==='alphabet'?'ASL LETTER':'REFERENCE LESSON';const title=document.createElement('h3');title.textContent=entry.label;const source=document.createElement('p');source.textContent=entry.source;const available=document.createElement('div');available.className='caption';available.textContent=status.label;const actions=document.createElement('div');actions.className='actions';const learn=document.createElement('button');learn.className='text-button';learn.textContent='Show / practice ↗';learn.onclick=()=>selectEntry(entry);const reference=document.createElement('a');reference.href=entry.referenceUrl;reference.target='_blank';reference.rel='noopener';reference.textContent='Source ↗';actions.append(learn,reference);card.append(badge,title,source,available,actions);$('catalog-results').append(card);}
    if(!result.entries.length){const empty=document.createElement('div');empty.className='library-empty';empty.textContent=loadError?'Reference loading failed. Reload to retry, or use the full-source links above.':'No indexed match. Try another spelling or open the full source dictionary.';$('catalog-results').append(empty);}
    $('catalog-count').textContent=`${result.total.toLocaleString()} reference entries · only trained signs are webcam-recognizable`;$('catalog-page').textContent=`Page ${result.page+1} of ${result.pages}`;$('catalog-prev').disabled=result.page===0;$('catalog-next').disabled=result.page>=result.pages-1;
    const count=catalog.filter(e=>e.language===lang).length;$('catalog-coverage').textContent=lang==='ISL'?`${count.toLocaleString()} official public-video references indexed${meta?.retrievedAt?' on '+meta.retrievedAt:''}. This is a directory snapshot, not every possible ISL sign or a pretrained model. The full official directory remains available above.`:`${count.toLocaleString()} ASL word/concept links plus the 26-letter chart. Lifeprint lessons open on their own site because their videos cannot be embedded here. Word meaning and regional variants matter.`;
  }
  function setLetters(){const box=$('catalog-letters');for(const value of ['',...'ABCDEFGHIJKLMNOPQRSTUVWXYZ']){const b=document.createElement('button');b.textContent=value||'All';b.classList.toggle('selected',!value);b.onclick=()=>{letter=value;page=0;[...box.children].forEach(c=>c.classList.toggle('selected',c===b));renderCatalog();};box.append(b);}}
  function clearAdvance(){clearTimeout(advanceTimer);advanceTimer=null;}
  function selectEntry(entry){clearAdvance();$('lesson-language').value=entry.language;$('fingerspell-fallback').disabled=entry.language!=='ASL';$('lesson-text').value=entry.label;plan={language:entry.language,input:entry.label,steps:[{kind:entry.kind==='alphabet'?'letter':'sign',text:entry.label,entry,alternatives:[]}],missing:[],fingerspelledWords:[],truncated:false};current=0;api.setLanguage(entry.language);renderPlan();api.navigate('learn');}
  function build(){clearAdvance();const text=$('lesson-text').value.trim();if(!text){api.toast('Type a word or phrase first.');return;}const lang=$('lesson-language').value;plan=makePlan(text,lang,entries(),{fingerspell:$('fingerspell-fallback').checked});current=0;api.setLanguage(lang);renderPlan();}
  function renderPlan(){
    if(!plan)return;
    const ready=plan.steps.filter(s=>s.entry&&recognitionStatus(s.entry,api.getEntries(),api.getModels()).ready).length;
    $('lesson-summary').textContent=`${plan.steps.length} practice step(s) · ${ready} webcam-recognizable · ${plan.missing.length} missing${plan.fingerspelledWords.length?' · fingerspelling: '+plan.fingerspelledWords.join(', '):''}${plan.truncated?' · long input was shortened':''}`;
    $('lesson-queue').replaceChildren();for(const [i,s] of plan.steps.entries()){const b=document.createElement('button');b.className='lesson-step'+(current===i?' selected':'');const num=document.createElement('span');num.textContent=String(i+1).padStart(2,'0');const label=document.createElement('span');label.textContent=s.kind==='letter'?`${s.text} · spelling ${s.word||s.text}`:s.text;const status=document.createElement('small');status.textContent=s.kind==='missing'?'Not indexed':recognitionStatus(s.entry,api.getEntries(),api.getModels()).ready?'Recognizable':'Reference';b.append(num,label,status);b.onclick=()=>{clearAdvance();current=i;renderPlan();};$('lesson-queue').append(b);}renderStep();
  }
  function referenceLink(entry,text){const a=document.createElement('a');a.className='secondary';a.href=entry.referenceUrl;a.target='_blank';a.rel='noopener';a.textContent=text;return a;}
  function renderStep(){
    const s=plan?.steps[current],stage=$('lesson-demonstration');stage.replaceChildren();$('lesson-alternatives').replaceChildren();$('practice-result').textContent='No accepted match yet.';$('practice-result').classList.remove('matched');
    $('lesson-prev').disabled=!s||current===0;$('lesson-next').disabled=!s||current===plan.steps.length-1;$('practice-train').disabled=!s?.entry;
    if(!s){$('lesson-current-label').textContent='Your next sign';$('lesson-step-count').textContent='—';$('lesson-instruction').textContent='';return;}
    $('lesson-current-label').textContent=s.entry?.label||s.text;$('lesson-step-count').textContent=`${current+1} / ${plan.steps.length}`;
    if(s.kind==='missing'){
      const title=document.createElement('h3');title.textContent='No verified demonstration in this snapshot';const p=document.createElement('p');p.textContent='Check the official dictionary or ask a fluent signer. This app does not invent a sign for an unknown word.';const a=document.createElement('a');a.className='secondary';a.href=plan.language==='ISL'?'https://drive.google.com/drive/folders/1U-Pr4r1-cupgNOOq9NH_uTsQnPSVEKco':'https://www.lifeprint.com/dictionary.htm';a.target='_blank';a.rel='noopener';a.textContent='Open full dictionary ↗';stage.append(title,p,a);$('lesson-instruction').textContent='Try another spelling or import a verified reference catalog.';$('practice-status').textContent='No target sign is available for this word.';return;
    }
    const e=s.entry;
    if(e.kind==='alphabet'){
      const alpha=ALPHABET.find(a=>a.letter===e.label.toUpperCase());if(alpha){const visual=document.createElement('div');visual.className='letter-visual';visual.style.backgroundPosition=`${52-alpha.x}px ${65-alpha.y}px`;visual.role='img';visual.setAttribute('aria-label',`ASL handshape for ${alpha.letter}${['J','Z'].includes(alpha.letter)?', including movement arrow':''}`);const label=document.createElement('strong');label.className='letter-label';label.textContent=alpha.letter;const b=document.createElement('button');b.className='text-button';b.textContent='View full alphabet chart ↗';b.onclick=()=>$('alphabet-dialog').showModal();stage.append(visual,label,b);}
    }else if(e.media){
      const intro=document.createElement('h3');intro.textContent=e.label;const p=document.createElement('p');p.textContent='Watch the source’s complete sign. Video loads from '+(e.media.type==='drive'?'Google Drive':'YouTube')+' when you select Play.';const play=document.createElement('button');play.className='primary';play.textContent='▷ Play demonstration';play.onclick=()=>{stage.replaceChildren();const frame=document.createElement('iframe');frame.src=e.media.type==='drive'?`https://drive.google.com/file/d/${e.media.id}/preview`:`https://www.youtube-nocookie.com/embed/${e.media.id}?rel=0`;frame.title=e.language+' demonstration: '+e.label;frame.allow='fullscreen; encrypted-media';frame.allowFullscreen=true;frame.referrerPolicy='strict-origin-when-cross-origin';stage.append(frame,referenceLink(e,'Open video separately ↗'));};stage.append(intro,p,play,referenceLink(e,'Open video separately ↗'));
    }else{
      const title=document.createElement('h3');title.textContent=e.source;const p=document.createElement('p');p.textContent=e.id==='asl-ily-starter'?'Use the handshape instructions below and try it on camera.':e.kind==='personal'?'This is your personally recorded sign. Refer to the verified lesson used to collect your examples.':'The source lesson shows how to perform this sign. Open it to watch the demonstration, then return to practice.';stage.append(title,p,referenceLink(e,e.kind==='personal'?'Open language resources ↗':'Open source sign lesson ↗'));
    }
    const provenance=document.createElement('p');provenance.className='caption demonstration-source';provenance.textContent=e.source;stage.append(provenance);
    $('lesson-instruction').textContent=e.instruction||'Watch the fingers, palm orientation, hand location, movement and facial expression. Perform the complete sign, then pause briefly. Use the source lesson to confirm the intended meaning.';
    if(s.alternatives?.length){const label=document.createElement('label');label.textContent='Other indexed meanings / variants';const select=document.createElement('select');const first=document.createElement('option');first.value='';first.textContent='Choose a different reference';select.append(first);s.alternatives.forEach((alt,i)=>{const o=document.createElement('option');o.value=String(i);o.textContent=alt.label+' · '+alt.source;select.append(o);});select.onchange=()=>{if(select.value==='')return;const alt=s.alternatives[Number(select.value)];s.alternatives=[s.entry,...s.alternatives.filter(a=>a.id!==alt.id)];s.entry=alt;renderPlan();};label.append(select);$('lesson-alternatives').append(label);}
    const status=recognitionStatus(e,api.getEntries(),api.getModels());$('practice-status').textContent=status.ready?`${status.label}. Enable the camera and perform “${e.label}”.`:`${status.label}. Record this sign and background examples before expecting webcam recognition.`;$('practice-train').textContent=status.ready?'Add more examples':'Train this sign';
  }
  function onRecognized(p){
    if($('view-learn').hidden||!plan?.steps[current]?.entry)return;const step=plan.steps[current],status=recognitionStatus(step.entry,api.getEntries(),api.getModels());const matched=status.ready&&p.id===status.id;
    $('practice-result').textContent=matched?`Matched “${p.label}”. This confirms the trained class, not every detail of your signing.`:`Camera recognized “${p.label}”. Current target: “${step.entry.label}”.`;
    $('practice-result').classList.toggle('matched',matched);
    if(matched&&$('practice-auto-next').checked&&current<plan.steps.length-1){clearAdvance();advanceTimer=setTimeout(()=>{current++;renderPlan();},1200);}
  }
  function refreshRecognition(){categories();renderCatalog();if(plan)renderPlan();}
  $('build-lesson').onclick=build;$('lesson-text').onkeydown=e=>{if(e.key==='Enter'&&(e.ctrlKey||e.metaKey)){e.preventDefault();build();}};
  $('lesson-language').onchange=()=>{clearAdvance();$('fingerspell-fallback').disabled=$('lesson-language').value!=='ASL';if(plan){plan=null;$('lesson-queue').replaceChildren();$('lesson-summary').textContent='Language changed. Select Show me the signs to rebuild your practice sequence.';renderStep();$('practice-status').textContent='Build a sequence for the selected language.';}api.setLanguage($('lesson-language').value);};
  document.querySelectorAll('[data-phrase]').forEach(b=>b.onclick=()=>{$('lesson-text').value=b.dataset.phrase;build();});
  $('lesson-prev').onclick=()=>{if(current>0){clearAdvance();current--;renderPlan();}};$('lesson-next').onclick=()=>{if(current<plan.steps.length-1){clearAdvance();current++;renderPlan();}};
  $('practice-camera').onclick=()=>{api.setLanguage(plan?.language||$('lesson-language').value);api.startCamera();};$('practice-stop-camera').onclick=()=>{clearAdvance();api.stopCamera();previewCtx.clearRect(0,0,preview.width,preview.height);};
  $('practice-train').onclick=()=>{const e=plan?.steps[current]?.entry;if(e)api.trainSign(e.language,e.label);else api.toast('Choose a sign before training.');};
  $('practice-auto-next').onchange=()=>clearAdvance();
  $('close-alphabet').onclick=()=>$('alphabet-dialog').close();
  $('catalog-language').onchange=()=>{page=0;categories();renderCatalog();};$('catalog-category').onchange=()=>{page=0;renderCatalog();};$('catalog-search').oninput=()=>{clearTimeout(searchTimer);searchTimer=setTimeout(()=>{page=0;renderCatalog();},120);};$('catalog-prev').onclick=()=>{page--;renderCatalog();};$('catalog-next').onclick=()=>{page++;renderCatalog();};setLetters();
  $('export-lesson').onclick=()=>{if(!plan){api.toast('Build a practice plan before exporting.');return;}api.download('signvoice-practice-plan.json',JSON.stringify({schemaVersion:1,type:'vocabulary-practice-not-translation',language:plan.language,input:plan.input,steps:plan.steps.map(s=>({kind:s.kind,text:s.text,spelledWord:s.word||null,label:s.entry?.label||null,source:s.entry?.source||null,referenceUrl:s.entry?.referenceUrl||null,recognition:s.entry?recognitionStatus(s.entry,api.getEntries(),api.getModels()).label:'Not indexed'}))},null,2));};
  $('import-reference').onchange=async event=>{const file=event.target.files[0];event.target.value='';if(!file)return;if(file.size>25*1024*1024){api.toast('Choose a reference JSON file smaller than 25 MB.');return;}try{const data=validateReferenceCatalog(JSON.parse(await file.text()));if(await api.confirmAction('Replace imported reference entries?',`Import ${data.entries.length} references? Bundled dictionaries and webcam recordings stay available. Only previously imported references are replaced.`)){await saveReferences(data.entries);imported=data.entries;refreshRecognition();api.toast('Reference catalog imported. This does not train webcam recognition.');}}catch(error){api.toast('Reference import failed: '+error.message);}};
  async function load(){try{const [asl,isl,m]=await Promise.all(['asl.json','isl.json','metadata.json'].map(name=>fetch(new URL('./catalog/'+name,import.meta.url)).then(r=>{if(!r.ok)throw Error('Catalog unavailable');return r.json();})));validateReferenceCatalog(asl);validateReferenceCatalog(isl);catalog=[...asl.entries,...isl.entries];meta=m;}catch{loadError=true;api.toast('Reference catalogs could not load. Full source dictionaries are linked in Sign library.');}try{const saved=await loadReferences();validateReferenceCatalog({schemaVersion:1,entries:saved});imported=saved;}catch{api.toast('Additional saved references could not load.');}refreshRecognition();}
  load();
  return {refreshRecognition,onRecognized,onView(view){clearAdvance();if(view==='learn')renderStep();},onCameraFrame(video,overlay,mirror){if($('view-learn').hidden)return;previewCtx.save();if(mirror){previewCtx.translate(preview.width,0);previewCtx.scale(-1,1);}previewCtx.drawImage(video,0,0,preview.width,preview.height);previewCtx.drawImage(overlay,0,0,preview.width,preview.height);previewCtx.restore();},onCameraStop(){clearAdvance();previewCtx.clearRect(0,0,preview.width,preview.height);},async clearImported(){await saveReferences([]);imported=[];plan=null;$('lesson-queue').replaceChildren();$('lesson-summary').textContent='Build a new practice sequence.';renderStep();refreshRecognition();}};
}
